251:             val id = occurrence(RuleKind.REWRITER, rule.ruleOrdinal(ordinal))
252:             if (forms.valid(rule) && !forms.rewriteSourceOrSink(rule, rewriter, projectNegatives = false).isFalse)
253:                 add(rule, id, rule.actionsAfter.mapIndexed { i, action -> rule.actionOrdinal(i) to action.position }, source = true)
254:         }
255:         val offset = sources.originalRuleCount()
256:         for ((ordinal, rule) in forms.rules.cleanerRulesForMethod(callee, s, fact = null, allRelevant = true).withIndex()) {
257:             val id = occurrence(RuleKind.REWRITER, offset + rule.ruleOrdinal(ordinal))
258:             if (forms.valid(rule) && rewriter.rewrite(rule.condition).isTrue)
