270:     private fun resolve(): Resolution {
271:         // A direct registered model is valid even when the ordinary resolver
272:         // would classify the generated method as external or unresolved.
273:         if (call is org.opentaint.ir.api.jvm.cfg.JIRStaticCallExpr) predefinedSummary(callee)?.let { model ->
274:             requireCatalogTarget(caller.method, callee)
275:             return Resolution(emptyList(), listOf(callee to model), false)
276:         }
277:         val context = object : JIRCallResolutionContext {
278:             override val methodEntryPoint = caller
279:             override val aliasAnalysis = this@JIRCallPlanBuilder.aliasAnalysis
280:         }
281:         val results = resolveCall(call, s, context)
282:         if (results.isEmpty()) return Resolution(emptyList(), emptyList(), true)
283:         val callees = LinkedHashSet<MethodKey>()
284:         val models = ArrayList<Pair<JIRMethod, CompleteMethodSummary>>()
285:         var unresolved = false
286:         var hasNonemptyTarget = false
287:         fun add(method: MethodWithContext) {
288:             val target = method.method as JIRMethod
289:             val model = predefinedSummary(target)
290:             if (model != null) {
291:                 requireCatalogTarget(caller.method, target)
292:                 hasNonemptyTarget = true
293:                 if (models.none { it.first === target }) models += target to model
294:                 return
295:             }
296:             if (target.instList.size == 0) return
297:             requireCatalogTarget(caller.method, method.method)
298:             hasNonemptyTarget = true
299:             callees += keys(method)
300:         }
301:         for (result in results) when (result) {
302:             JIRCallResolver.MethodResolutionResult.MethodResolutionFailed -> unresolved = true
303:             is JIRCallResolver.MethodResolutionResult.ConcreteMethod -> add(result.method)
304:             is JIRCallResolver.MethodResolutionResult.Lambda -> {
305:                 val implementations = lambdas[s.location.index]
306:                 if (implementations.isNullOrEmpty()) unresolved = true
307:                 else implementations.forEach { add(MethodWithContext(it, EmptyMethodContext)) }
308:             }
309:         }
310:         if (!hasNonemptyTarget) unresolved = true
311:         return Resolution(callees.toList(), models, unresolved)
312:     }

